// spec: .qa/e2e/specs/landing-jobs-block.md
// seed: tests/seed.spec.ts

import { test, expect } from '@playwright/test';

test.describe('Headhunters landing jobs block', () => {
  test('Jobs block shows 14 different jobs in two rows (en) @desktop @prod-safe (#d9ffaa)', async ({ page }) => {
    // 1. Open /en/headhunters as guest.
    await page.goto('/en/headhunters');

    // 2. Scroll to the jobs block ("Just some of the jobs waiting inside").
    const heading = page.getByRole('heading', { name: 'Just some of the jobs waiting inside' });
    await heading.scrollIntoViewIfNeeded();
    await expect(heading).toBeVisible();
    const block = page.locator('section').filter({ has: heading });
    const cards = block.locator('article');
    await expect(cards.first()).toBeVisible();

    // 3. Collect the job cards, grouped by row (same top offset = same row); read each card title.
    const collected = await cards.evaluateAll((els) =>
      els.map((a) => ({
        top: Math.round(a.getBoundingClientRect().top + window.scrollY),
        title: a.querySelector('h3')?.textContent?.trim() ?? '',
        location: a.querySelector('p')?.textContent?.trim() ?? '',
        salary: a.querySelector('dd')?.textContent?.trim() ?? '',
      })),
    );

    const rows = new Map<number, typeof collected>();
    for (const c of collected) {
      const key = [...rows.keys()].find((k) => Math.abs(k - c.top) <= 2) ?? c.top;
      rows.set(key, [...(rows.get(key) ?? []), c]);
    }

    // Exactly 2 rows with 7 cards each (14 cards).
    expect(collected).toHaveLength(14);
    expect(rows.size).toBe(2);
    for (const row of rows.values()) expect(row).toHaveLength(7);

    // All 14 card titles are different.
    const titles = collected.map((c) => c.title);
    expect(new Set(titles).size, `duplicate titles: ${titles.join(' | ')}`).toBe(14);

    // Every card has a title, a location and a salary range.
    for (const c of collected) {
      expect(c.title).not.toBe('');
      expect(c.location, `location of ${c.title}`).not.toBe('');
      expect(c.salary, `salary of ${c.title}`).toMatch(/\d[\d,]*\s*-\s*\d[\d,]*/);
    }
  });
});
